31:     f.eval(": o n n ;").unwrap();
32:     f.eval(": p o o ;").unwrap();
33:     f.eval(": q p p ;").unwrap();
34:     f.eval(": r q q ;").unwrap();
35:     f.eval(": s r r ;").unwrap();
36:     f.eval(": t s s ;").unwrap();
37:     f.eval(": u t t ;").unwrap();
38:     f.eval(": v u u ;").unwrap();
39:     f.eval(": w v v ;").unwrap();
40:     f.eval(": x w w ;").unwrap();
