            loop {
                if i >= tokens.len() {
                    // unterminated definition — treat as error? 
                    return Err(Error::InvalidWord);
                }
                if tokens[i] == ";" {
                    i += 1;
                    break;
                }
                body.push(tokens[i]);
                i += 1;
